// The response-tracker reference design, stage 1 (schedulable-library-plan.md §6.8).
//
//   req ──► rt_tag ──q (RT_Q_DEPTH)──► rt_resp ──► rsp
//
// rt_tag gives each request the next tag (a rolling 4-bit count); rt_resp
// answers it with {tag, 3 * addr}. Responses leave in request order.
//
// One source, many schedules: the queue depth comes from the knob file's
// rtl: section (rt_top_knobs_pkg, generated by fw.hdl.knobs.Resolve); stages,
// channel registers and latency contracts come from its xls: and contracts:
// sections. Later stages add the keyed table, slot pool, out-of-order returns
// and a credited release loop.
package rt_pkg;
    import fw_hdl_pkg::*;
    import fw_std_pkg::*;
    import rt_top_knobs_pkg::*;

    typedef bit [7:0]  req_t;       // address
    typedef bit [11:0] tagged_t;    // {tag[3:0], address}
    typedef bit [15:0] rsp_t;       // {tag[3:0], data[11:0]}

    class rt_tag extends fw_component implements fw_runnable;
        fw_port #(fw_get_if #(req_t))    in;
        fw_port #(fw_put_if #(tagged_t)) out;
        bit [3:0] tag;

        function new(string name, fw_component parent);
            super.new(name, parent);
            add_runnable(this);
        endfunction
        function void build();
            in = new("in", this);
            out = new("out", this);
        endfunction
        virtual task run();
            forever begin
                req_t a;
                in.t.get(a);
                out.t.put({tag, a});
                tag = tag + 4'd1;
            end
        endtask
    endclass

    class rt_resp extends fw_component implements fw_runnable;
        fw_port #(fw_get_if #(tagged_t)) in;
        fw_port #(fw_put_if #(rsp_t))    out;

        function new(string name, fw_component parent);
            super.new(name, parent);
            add_runnable(this);
        endfunction
        function void build();
            in = new("in", this);
            out = new("out", this);
        endfunction
        virtual task run();
            forever begin
                tagged_t t;
                bit [11:0] d;
                in.t.get(t);
                d = 12'(t[7:0]) * 12'd3;
                out.t.put({t[11:8], d});
            end
        endtask
    endclass

    class rt_top extends fw_component;
        fw_port #(fw_get_if #(req_t)) req;
        fw_port #(fw_put_if #(rsp_t)) rsp;
        rt_tag                           tagger;
        rt_resp                          responder;
        fw_channel #(tagged_t, RT_Q_DEPTH) q;

        function new(string name, fw_component parent);
            super.new(name, parent);
        endfunction
        function void build();
            req = new("req", this);
            rsp = new("rsp", this);
            tagger = new("tagger", this);
            responder = new("responder", this);
            q = new("q", this);
        endfunction
        function void connect();
            tagger.in.connect(req);
            tagger.out.connect(q.put_ex);
            responder.in.connect(q.get_ex);
            responder.out.connect(rsp);
        endfunction
    endclass
endpackage
